content.content:
  1	package hotel.reservations;
  2	
  3	import hotel.documents.ReservationReceipt;
  4	import hotel.messages.EmailSender;
  5	import hotel.notifications.ReservationListener;
  6	import hotel.rooms.Room;
  7	import hotel.rooms.Rooms;
  8	import java.math.BigDecimal;
  9	import java.util.List;
 10	
 11	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 12	public final class ReservationService {
 13	
 14	    static final String HOTEL_NAME = "Pousada Maré Alta";
 15	
 16	    private final Rooms rooms;
 17	    private final ReservationStore store;
 18	    private final PriceCalculator priceCalculator;
 19	    private final EmailSender emailSender;
 20	    private final List<ReservationListener> listeners;
 21	
 22	    public ReservationService(
 23	            Rooms rooms,
 24	            ReservationStore store,
 25	            PriceCalculator priceCalculator,
 26	            EmailSender emailSender,
 27	            List<ReservationListener> listeners) {
 28	        this.rooms = rooms;
 29	        this.store = store;
 30	        this.priceCalculator = priceCalculator;
 31	        this.emailSender = emailSender;
 32	        this.listeners = listeners;
 33	    }
 34	
 35	    public synchronized Reservation create(NewReservation request) {
 36	        if (!request.checkOut().isAfter(request.checkIn())) {
 37	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 38	        }
 39	        if (request.guests() < 1) {
 40	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 41	        }
 42	        Room room = rooms.find(request.roomNumber())
 43	                .orElseThrow(() -> new HotelException(
 44	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 45	        if (request.guests() > room.capacity()) {
 46	            throw new HotelException(
 47	                    ErrorCode.CAPACITY_EXCEEDED,
 48	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 49	        }
 50	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 51	            throw new HotelException(
 52	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 53	        }
 54	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 55	        return store.add(request, price);
 56	    }
 57	
 58	    public Reservation find(long reservationId) {
 59	        return store.find(reservationId)
 60	                .orElseThrow(() -> new HotelException(
 61	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 62	    }
 63	
 64	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 65	    public synchronized Reservation confirm(long reservationId) {
 66	        Reservation reservation = find(reservationId);
 67	        if (reservation.status() != ReservationStatus.PENDING) {
 68	            throw notAllowed(reservation, "confirm");
 69	        }
 70	        reservation.confirmPayment();
 71	        store.update(reservation);
 72	        Room room = roomOf(reservation);
 73	        ReservationReceipt receipt = new ReservationReceipt(reservation, room);
 74	        emailSender.send(
 75	                reservation.guest().email(),
 76	                "Reserva confirmada - " + HOTEL_NAME,
 77	                confirmationEmailBody(reservation, receipt));
 78	        for (ReservationListener listener : listeners) {
 79	            listener.onConfirmed(reservation, room);
 80	        }
 81	        return reservation;
 82	    }
 83	
 84	    /**
 85	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 86	     * reservation was never paid, so nothing comes back).
 87	     */
 88	    public synchronized Reservation cancel(long reservationId) {
 89	        Reservation reservation = find(reservationId);
 90	        if (reservation.status() != ReservationStatus.PENDING
 91	                && reservation.status() != ReservationStatus.CONFIRMED) {
 92	            throw notAllowed(reservation, "cancel");
 93	        }
 94	        BigDecimal refund = switch (reservation.ratePlan()) {
 95	            case STANDARD -> reservation.amountPaid();
 96	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 97	        };
 98	        reservation.cancel(refund);
 99	        store.update(reservation);
100	        for (ReservationListener listener : listeners) {
101	            listener.onCancelled(reservation, roomOf(reservation));
102	        }
103	        return reservation;
104	    }
105	
106	    public synchronized Reservation checkIn(long reservationId) {
107	        Reservation reservation = find(reservationId);
108	        if (reservation.status() != ReservationStatus.CONFIRMED) {
109	            throw notAllowed(reservation, "check in");
110	        }
111	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
112	        store.update(reservation);
113	        return reservation;
114	    }
115	
116	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
117	    public synchronized ReservationReceipt checkOut(long reservationId) {
118	        Reservation reservation = find(reservationId);
119	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
120	            throw notAllowed(reservation, "check out");
121	        }
122	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
123	        store.update(reservation);
124	        return new ReservationReceipt(reservation, roomOf(reservation));
125	    }
126	
127	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
128	    public ReservationReceipt receiptCopy(long reservationId) {
129	        Reservation reservation = find(reservationId);
130	        if (!reservation.isPaid()) {
131	            throw notAllowed(reservation, "issue a receipt for");
132	        }
133	        return new ReservationReceipt(reservation, roomOf(reservation));
134	    }
135	
136	    private Room roomOf(Reservation reservation) {
137	        return rooms.find(reservation.roomNumber()).orElseThrow();
138	    }
139	
140	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
141	        return "Olá, " + reservation.guest().name() + "!\n\n"
142	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
143	                + receipt.text() + "\n"
144	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
145	                + "Até breve!\n";
146	    }
147	
148	    private static HotelException notAllowed(Reservation reservation, String operation) {
149	        return new HotelException(
150	                ErrorCode.OPERATION_NOT_ALLOWED,
151	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
152	    }
153	}
