 18	    private BigDecimal refund;
 19	
 20	    Reservation(long id, NewReservation request, Price price) {
 21	        this(id, request, price, ReservationStatus.PENDING, PriceCalculator.cents(BigDecimal.ZERO), null);
 22	    }
 23	
 24	    Reservation(
 25	            long id,
 26	            NewReservation request,
 27	            Price price,
 28	            ReservationStatus status,
 29	            BigDecimal amountPaid,
 30	            BigDecimal refund) {
 31	        this.id = id;
 32	        this.roomNumber = request.roomNumber();
 33	        this.guest = request.guest();
 34	        this.checkIn = request.checkIn();
 35	        this.checkOut = request.checkOut();
 36	        this.guests = request.guests();
 37	        this.ratePlan = request.ratePlan();
 38	        this.price = price;
 39	        this.status = status;
 40	        this.amountPaid = amountPaid;
 41	        this.refund = refund;
 42	    }
 43	
 44	    public long id() {
 45	        return id;
 46	    }
 47	
 48	    public int roomNumber() {
 49	        return roomNumber;
 50	    }
 51	
 52	    public Guest guest() {
 53	        return guest;
 54	    }
 55	
 56	    public LocalDate checkIn() {
 57	        return checkIn;
 58	    }
 59	
 60	    public LocalDate checkOut() {
 61	        return checkOut;
 62	    }
 63	
 64	    public int guests() {
 65	        return guests;
 66	    }
 67	
 68	    public RatePlan ratePlan() {
 69	        return ratePlan;
 70	    }
 71	
 72	    public Price price() {
 73	        return price;
 74	    }
 75	
 76	    public ReservationStatus status() {
 77	        return status;
 78	    }
 79	
 80	    /** What the guest paid: the total, once the reservation is confirmed; zero before that. */
 81	    public BigDecimal amountPaid() {
 82	        return amountPaid;
 83	    }
 84	
 85	    /** What the guest got back when the reservation was cancelled; null while it is not cancelled. */
 86	    public BigDecimal refund() {
 87	        return refund;
 88	    }
 89	
 90	    /** Confirmed, checked in or checked out: the guest paid and the room is theirs. */
